"use client";
import { useRef } from "react";
import { useTypeMotion, type TypographyMotionProps, typeInteractive } from "./typography-shared";
import { typeEaseOut } from "./typography-math";
export interface TextSplitZoomProps extends Omit<TypographyMotionProps, "text"> {
  leftText?: string;
  rightText?: string;
  image?: string;
  alt?: string;
  scaleStart?: number;
  scaleEnd?: number;
  aspectRatio?: number;
  imageWidth?: number;
  gap?: number;
}
export function TextSplitZoom({
  leftText = "Attack",
  rightText = "the Hill",
  image,
  alt = "",
  scaleStart = 0.04,
  scaleEnd = 1,
  aspectRatio = 0.75,
  imageWidth = 28,
  gap = 12,
  ...props
}: TextSplitZoomProps) {
  const root = useRef<HTMLDivElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const q = typeEaseOut(p),
        scale = scaleStart + (scaleEnd - scaleStart) * q;
      const media = root.current!.querySelector<HTMLElement>("[data-type-zoom]")!;
      media.style.width = `${Math.max(0, Math.min(65, imageWidth * scale))}%`;
      media.style.marginInline = `${gap * q}px`;
      media.style.clipPath = `inset(${(1 - q) * 10}% round ${4 * q}px)`;
      const image = media.firstElementChild as HTMLElement;
      if (image) image.style.transform = `scale(${1.5 - 0.5 * q})`;
    },
    `${leftText}:${rightText}:${scaleStart}:${scaleEnd}:${aspectRatio}:${imageWidth}:${gap}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        overflow: "clip",
        ...props.style,
      }}
      data-typography="text-split-zoom"
      {...typeInteractive(props.trigger)}
    >
      <span style={{ flexShrink: 0 }}>{leftText}</span>
      <div
        data-type-zoom=""
        style={{
          width: `${imageWidth}%`,
          aspectRatio,
          flexShrink: 0,
          overflow: "hidden",
          marginInline: gap,
          background: "#b4c5bf",
        }}
      >
        {image ? (
          <img
            src={image}
            alt={alt}
            style={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        ) : (
          <div
            role="img"
            aria-label={alt || "Abstract terrain"}
            style={{
              width: "100%",
              height: "100%",
              background:
                "linear-gradient(145deg,#182923 0 30%,#99bfa1 30% 45%,#567262 45% 60%,#d8d1bb 60%)",
            }}
          />
        )}
      </div>
      <span style={{ flexShrink: 0 }}>{rightText}</span>
    </div>
  );
}
